import path from "node:path";
import { IMPORTED_MEDIA_DIRECTORY_NAME, LEGACY_IMPORTED_MEDIA_DIRECTORY_NAMES } from "./recordingFileNames";

/** Sources generated by Videos imports have independent, lossless audio companions. */
export function isLibrarySequenceSource(file: string): boolean {
	return (
		[IMPORTED_MEDIA_DIRECTORY_NAME, ...LEGACY_IMPORTED_MEDIA_DIRECTORY_NAMES].includes(path.basename(path.dirname(file))) &&
		/^[0-9a-f-]{36}\.mp4$/.test(path.basename(file))
	);
}
